  "We guessed these from your listing. Check them and save, so we can show you the right tools and send you the right couples.": "यी हामीले तपाईंको सूचीबाट अनुमान गर्यौं। जाँचेर सुरक्षित गर्नुहोस्, ताकि सही औजार देखाउन र सही जोडी पठाउन सकौं।",
