  "We’ll email you when it’s done. Then sign in with your email again and the operations console opens.": "सकिएपछि इमेल गर्छौं। त्यसपछि फेरि इमेलबाट साइन इन गर्नुहोस्, सञ्चालन कन्सोल खुल्छ।",
  "We’ll immediately start an emergency replacement so the couple isn’t affected. Frequent cancellations lower your reliability score.": "जोडीलाई असर नपरोस् भनेर हामी तुरुन्तै आपतकालीन व्यक्ति खोज्न थाल्छौं। बारम्बार रद्द गर्दा तपाईंको भरपर्दोपन घट्छ।",
  "We’ll show venues and vendors who work there.": "त्यहाँ काम गर्ने भेन्यु र सेवाप्रदायक देखाउँछौं।",
